def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    if n == 0:
        return [""]

    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            field_chars = []
            closed = False
            while True:
                if i >= n:
                    # unterminated quoted field
                    return None
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        # closing quote
                        i += 1
                        closed = True
                        break
                else:
                    field_chars.append(c)
                    i += 1
            if not closed:
                return None
            # after closing quote, must be comma or end
            if i == n:
                fields.append("".join(field_chars))
                break
            elif line[i] == ',':
                fields.append("".join(field_chars))
                i += 1
                if i == n:
                    # trailing comma means an empty field after
                    fields.append("")
                    break
                continue
            else:
                return None
        else:
            # unquoted field
            start = i
            comma_pos = line.find(',', i)
            if comma_pos == -1:
                field_str = line[start:n]
                if '"' in field_str:
                    return None
                fields.append(field_str)
                i = n
                break
            else:
                field_str = line[start:comma_pos]
                if '"' in field_str:
                    return None
                fields.append(field_str)
                i = comma_pos + 1
                if i == n:
                    fields.append("")
                    break
                continue

    return fields

